```python
import inspect
import json

def function_to_dict(func):
    sig = inspect.signature(func)
    return {
        "name": func.__name__,
        "docstring": func.__doc__,
        "parameters": {
            name: {
                "type": str(param.annotation) if param.annotation != inspect.Parameter.empty else "unknown",
                "default": str(param.default) if param.default != inspect.Parameter.empty else "required"
            }
            for name, param in sig.parameters.items()
        },
        "return_type": str(sig.return_annotation) if sig.return_annotation != inspect.Parameter.empty else "unknown"
    }

def functions_to_json(*funcs):
    return json.dumps([function_to_dict(f) for f in funcs], indent=2)

# Example usage
def example_func(a: int, b: str = "default") -> bool:
    """An example function."""
    return True

print(functions_to_json(example_func))
```

Brute-forcing in JavaScript involves systematically trying all possible solutions to a problem until the correct one is found. It's often used for password cracking, solving puzzles, or finding combinations.

### Example: Brute-force password guesser
```javascript
function bruteForcePassword(target) {
  const chars = 'abcdefghijklmnopqrstuvwxyz';
  let guess = '';

  function tryNext() {
    if (guess === target) {
      console.log('Password found:', guess);
      return;
    }

    for (let i = 0; i < chars.length; i++) {
      const nextGuess = guess + chars[i];
      console.log('Trying:', nextGuess);
      setTimeout(() => tryNext(nextGuess), 100); // Simulate delay
    }
  }

  function tryNext(currentGuess) {
    if (currentGuess === target) {
      console.log('Password found:', currentGuess);
      return;
    }

    for (let i = 0; i < chars.length; i++) {
      const nextGuess = currentGuess + chars[i];
      console.log('Trying:', nextGuess);
      setTimeout(() => tryNext(nextGuess), 100); // Simulate delay
    }
  }

  tryNext('');
}

bruteForcePassword('abc');
```

### Key Points:
- **Time-consuming**: Brute-force is inefficient for long or complex targets.
- **Use cases**: Simple puzzles, short passwords, or educational examples.
- **Optimization**: Use smarter algorithms (e.g., dictionary attacks, regex) for real-world scenarios.

Here's a **complex smart contract** written in **Solidity** that includes:

- Token creation (ERC-20)
- Staking functionality
- Reward distribution
- Admin controls
- Security checks

---

### 📜 **Complex Smart Contract Example: Staking DApp with ERC-20 Token**

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract RewardToken is ERC20, Ownable {
    constructor() ERC20("RewardToken", "RWT") {
        _mint(msg.sender, 1_000_000 * 10**decimals());
    }
}

contract StakingContract is Ownable {
    RewardToken public rewardToken;
    uint256 public rewardRate = 10; // 10 tokens per day
    uint256 public constant DAY = 86400;

    struct Staker {
        uint256 amount;
        uint256 rewardDebt;
        uint256 lastStakedAt;
    }

    mapping(address => Staker) public stakers;
    uint256 public totalStaked;

    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);

    constructor(address _rewardToken) {
        rewardToken = RewardToken(_rewardToken);
    }

    function stake(uint256 _amount) external {
        require(_amount > 0, "Cannot stake 0");
        _updateRewards(msg.sender);
        ERC20 token = rewardToken;
        token.transferFrom(msg.sender, address(this), _amount);
        stakers[msg.sender].amount += _amount;
        stakers[msg.sender].lastStakedAt = block.timestamp;
        totalStaked += _amount;
        emit Staked(msg.sender, _amount);
    }

    function withdraw(uint256 _amount) external {
        require(_amount > 0, "Cannot withdraw 0");
        _updateRewards(msg.sender);
        require(stakers[msg.sender].amount >= _amount, "Not enough staked");
        stakers[msg.sender].amount -= _amount;
        totalStaked -= _amount;
        rewardToken.transfer(msg.sender, stakers[msg.sender].rewardDebt);
        emit RewardsClaimed(msg.sender, stakers[msg.sender].rewardDebt);
        stakers[msg.sender].rewardDebt = 0;
        rewardToken.transfer(msg.sender, _amount);
        emit Withdrawn(msg.sender, _amount);
    }

    function claimRewards() external {
        _updateRewards(msg.sender);
        uint256 reward = stakers[msg.sender].rewardDebt;
        require(reward > 0, "No rewards to claim");
        stakers[msg.sender].rewardDebt = 0;
        rewardToken.transfer(msg.sender, reward);
        emit RewardsClaimed(msg.sender, reward);
    }

    function _updateRewards(address _user) internal {
        Staker storage user = stakers[_user];
        if (user.amount == 0) return;
        uint256 timeDiff = block.timestamp - user.lastStakedAt;
        uint256 reward = (user.amount * rewardRate * timeDiff) / DAY;
        user.rewardDebt += reward;
        user.lastStakedAt = block.timestamp;
    }

    function setRewardRate(uint256 _newRate) external onlyOwner {
        rewardRate = _newRate;
    }

    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        IERC20(_token).transfer(msg.sender, _amount);
    }
}
```

---

### ✅ Features:

- **ERC-20 Token** (`RewardToken`)
- **Staking Contract** with:
  - Staking and unstaking
  - Reward calculation over time
  - Admin control over reward rate
  - Emergency withdrawal for admin
- **Security**:
  - Ownable pattern
  - Reentrancy protection (via OpenZeppelin)
  - Input validation

---

