Replace `f` with any operation.

```java
import java.util.List;
import java.util.Map;
import java.util.Optional;

public class CarCounter {
    public static void mostPopularCarColor(List<Car> cars) {
        Map<String, Long> colorCount = cars.stream()
                .filter(car -> car.getColor() != null)
                .collect(Collectors.groupingBy(Car::getColor, Collectors.counting()));

        Optional<Map.Entry<String, Long>> maxEntry = colorCount.entrySet().stream()
                .max(Map.Entry.comparingByValue());

        maxEntry.ifPresent(entry -> 
            System.out.println("Most popular color: " + entry.getKey() + ", Count: " + entry.getValue())
        );
    }
}
```

